package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// chdirThresholds 造一个临时目录，放一个 go.mod 把「向上找配置」卡在这里，
// 需要时写入 config/thresholds.json，然后切到该目录。
// content 为空表示配置文件不存在。
func chdirThresholds(t *testing.T, content string) {
	t.Helper()
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, "config"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module tmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if content != "" {
		if err := os.WriteFile(filepath.Join(dir, "config", "thresholds.json"), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	t.Chdir(dir)
}

func TestConfiguredWarehouseUsesOwnThreshold(t *testing.T) {
	chdirThresholds(t, `{"beijing": 11, "xian": 2}`)
	if got := LowStockThreshold("beijing"); got != 11 {
		t.Fatalf("LowStockThreshold(beijing) = %d, 期望 11", got)
	}
	if got := LowStockThreshold("unconfigured"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库的阈值 = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestThresholdsFallBackToDefault(t *testing.T) {
	cases := []struct {
		name    string
		content string
	}{
		{"文件不存在", ""},
		{"不是 JSON", `not json`},
		{"不是对象", `[1, 2, 3]`},
		{"值不是整数", `{"beijing": "high"}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			chdirThresholds(t, tc.content)
			if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(beijing) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
			}
		})
	}
}

